#!/usr/bin/env python3
"""Merge user data from three heterogeneous sources into one Parquet file.

Priority: source_a > source_b > source_c.
Outputs /app/merged_users.parquet and /app/conflicts.json
"""
from __future__ import annotations

import csv
import json
import math
import os
from datetime import date, datetime

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

# canonical field -> accepted source field names (lowercased, non-alnum stripped)
ALIASES = {
    "user_id": ["user_id", "id", "userid", "uid"],
    "email": ["email", "email_address", "emailaddress", "mail"],
    "name": ["full_name", "name", "username", "fullname", "user_name"],
    "created_date": [
        "registration_date",
        "created_at",
        "joined",
        "created_date",
        "registrationdate",
        "createdat",
        "joined_date",
        "signup_date",
        "date_joined",
    ],
    "status": ["status", "is_active", "active", "isactive", "state", "account_status"],
}
FIELDS = ["name", "email", "created_date", "status"]


def _norm_key(k: str) -> str:
    return "".join(ch for ch in str(k).lower() if ch.isalnum() or ch == "_")


def _canonical(key: str) -> str | None:
    nk = _norm_key(key)
    nk_nounder = nk.replace("_", "")
    for canon, names in ALIASES.items():
        for cand in names:
            if nk == cand or nk_nounder == cand.replace("_", ""):
                return canon
    return None


def _is_missing(v) -> bool:
    if v is None:
        return True
    if isinstance(v, float) and math.isnan(v):
        return True
    if isinstance(v, str) and v.strip() == "":
        return True
    try:
        if v is pd.NaT or (not isinstance(v, (list, dict, tuple)) and pd.isna(v)):
            return True
    except (TypeError, ValueError):
        pass
    return False


def _to_status(v):
    if _is_missing(v):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    low = s.lower()
    if low in ("true", "1", "yes", "y", "t"):
        return "active"
    if low in ("false", "0", "no", "n", "f"):
        return "inactive"
    return s


def _to_date(v):
    """Normalize any reasonable date representation to YYYY-MM-DD."""
    if _is_missing(v):
        return None
    if isinstance(v, datetime):
        return v.date().isoformat()
    if isinstance(v, date):
        return v.isoformat()
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        # epoch seconds / millis
        n = float(v)
        unit = "ms" if abs(n) > 1e11 else "s"
        try:
            return pd.to_datetime(n, unit=unit).date().isoformat()
        except (ValueError, OverflowError, pd.errors.OutOfBoundsDatetime):
            return str(v)
    s = str(v).strip()
    for fmt in (
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%d/%m/%Y",
        "%m/%d/%Y",
        "%d-%m-%Y",
        "%Y%m%d",
        "%d.%m.%Y",
        "%b %d, %Y",
        "%B %d, %Y",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
    ):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            continue
    try:
        parsed = pd.to_datetime(s, errors="coerce")
    except (ValueError, TypeError):
        parsed = None
    if parsed is not None and not _is_missing(parsed):
        return parsed.date().isoformat()
    return s


def _to_user_id(v):
    if _is_missing(v):
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int,)):
        return int(v)
    if isinstance(v, float):
        return int(v)
    s = str(v).strip()
    digits = "".join(ch for ch in s if ch.isdigit() or ch == "-")
    try:
        return int(digits)
    except ValueError:
        return None


def load_records(path: str) -> list[dict]:
    ext = os.path.splitext(path)[1].lower()
    if ext == ".json":
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            for key in ("users", "data", "records", "results"):
                if isinstance(data.get(key), list):
                    data = data[key]
                    break
            else:
                data = [data]
        return [r for r in data if isinstance(r, dict)]
    if ext in (".csv", ".tsv", ".txt"):
        with open(path, "r", encoding="utf-8", newline="") as fh:
            sample = fh.read(4096)
            fh.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
            return [dict(row) for row in csv.DictReader(fh, dialect=dialect)]
    if ext in (".parquet", ".pq"):
        return pd.read_parquet(path).to_dict(orient="records")
    raise ValueError(f"unsupported input format: {path}")


def normalize(record: dict) -> dict:
    out: dict = {}
    for raw_key, raw_val in record.items():
        canon = _canonical(raw_key)
        if canon is None or canon in out:
            continue
        if canon == "user_id":
            val = _to_user_id(raw_val)
        elif canon == "created_date":
            val = _to_date(raw_val)
        elif canon == "status":
            val = _to_status(raw_val)
        else:
            val = None if _is_missing(raw_val) else str(raw_val).strip()
        if val is not None:
            out[canon] = val
    return out


def main() -> None:
    per_source: dict[str, dict[int, dict]] = {}
    order: list[int] = []
    for source_name, path in SOURCES:
        bucket: dict[int, dict] = {}
        if os.path.exists(path):
            for raw in load_records(path):
                rec = normalize(raw)
                uid = rec.get("user_id")
                if uid is None:
                    continue
                if uid in bucket:
                    bucket[uid].update({k: v for k, v in rec.items()})
                else:
                    bucket[uid] = rec
                    if uid not in order:
                        order.append(uid)
        per_source[source_name] = bucket

    priority = [name for name, _ in SOURCES]
    merged_rows = []
    conflicts = []

    for uid in sorted(order):
        row = {"user_id": int(uid)}
        for field in FIELDS:
            values = {}
            for src in priority:
                rec = per_source[src].get(uid)
                if rec is not None and field in rec:
                    values[src] = rec[field]
            if not values:
                row[field] = None
                continue
            selected = next(values[s] for s in priority if s in values)
            row[field] = selected
            if len({str(v) for v in values.values()}) > 1:
                conflicts.append(
                    {
                        "user_id": int(uid),
                        "field": field,
                        "values": {s: values[s] for s in priority if s in values},
                        "selected": selected,
                    }
                )
        merged_rows.append(row)

    df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        df[col] = df[col].astype(object).where(df[col].notna(), None)
        df[col] = df[col].map(lambda v: None if v is None else str(v))
    df.to_parquet(OUT_PARQUET, index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2)
        fh.write("\n")

    print(df.to_string(index=False))
    print(f"users={len(df)} conflicts={len(conflicts)}")


if __name__ == "__main__":
    main()

